const inputs = [exp.input, ...st.slice(0, -1)];

const mods = [991, 997, 999, 1000, 1001, 1009, 1021, 1024, 1031, 2000, 4096, 8192, 65536, 2**31, 1000003];

const results = [];
for (let i = 1; i <= 32; i++) {
  const v = inputs[i - 1], out = st[i - 1];
  const cands = [];
  // (v + floor(v/d) + c) % m
  for (const m of mods) for (let d = 1; d <= 32; d++) for (let c = -32; c <= 32; c++) {
    if (((v + Math.floor(v / d) + c) % m + m) % m === out) cands.push(`(v + Math.floor(v/${d}) + ${c}) % ${m}`);
  }
  // (v * a + c) % m
  for (const m of mods) for (let a = -8; a <= 32; a++) for (let c = -64; c <= 64; c++) {
    if (((v * a + c) % m + m) % m === out) cands.push(`(v * ${a} + ${c}) % ${m}`);
  }
  // v ^ k
  for (let k = 0; k < 4096; k++) if ((v ^ k) === out) cands.push(`v ^ ${k}`);
  // (v ^ k) % m
  for (const m of mods) for (let k = 0; k < 512; k++) if (((v ^ k) % m + m) % m === out) cands.push(`(v ^ ${k}) % ${m}`);
  // shifts and mixes
  for (let s = 1; s < 16; s++) for (let c = 0; c < 64; c++) {
    if (((v << s) ^ c) === out) cands.push(`(v << ${s}) ^ ${c}`);
    if (((v << s) + c) === out) cands.push(`(v << ${s}) + ${c}`);
  }
  results.push({ stage: i, v, out, n: cands.length, cands: cands.slice(0, 40) });
}
for (const r of results) {
  console.log(`--- stage ${r.stage}: ${r.v} -> ${r.out}  (${r.n} cands)`);
  console.log("   " + r.cands.join("\n   "));
}

