import { readFileSync } from "node:fs";
const exp = JSON.parse(readFileSync(new URL("../tests/expected.json", import.meta.url), "utf8"));
const st = exp.stages;

// 假设：i = 级号(1..32)，四种公式按 i%4 循环
function step(n, v) {
  switch (n % 4) {
    case 1: return (v + Math.floor(v / 3)) % 997;
    case 2: return v ^ ((n * 7) % 64);
    case 3: return (v * 3 - n) % 991;
    case 0: return (v * 2 + 1) % 1000;
  }
}
let v = exp.input, bad = 0;
for (let n = 1; n <= 32; n++) {
  v = step(n, v);
  const ok = v === st[n - 1];
  if (!ok) bad++;
  console.log(`s${String(n).padStart(2, "0")} -> ${v} 期望 ${st[n - 1]} ${ok ? "OK" : "X"}`);
}
console.log(bad === 0 ? "全部 32 级吻合" : `${bad} 级不符`);

import { readFileSync } from "node:fs";
const exp = JSON.parse(readFileSync(new URL("../tests/expected.json", import.meta.url), "utf8"));
const st = exp.stages;
const inputs = [exp.input, ...st.slice(0, -1)];

const MODS = [];
for (const m of [991, 997, 999, 1000, 1001, 1009, 1021, 1024, 1031, 2048, 4096, 8192, 65536, 2**31, 1000003, 1000000007]) MODS.push(m);

const mod = (a, m) => ((a % m) + m) % m;

for (let n = 1; n <= 32; n++) {
  const v = inputs[n - 1], out = st[n - 1];
  const cands = [];
  for (const m of MODS) {
    for (let d = 1; d <= 16; d++) for (let c = -64; c <= 64; c++) {
      if (mod(v + Math.floor(v / d) + c, m) === out) cands.push(`(v + Math.floor(v/${d}) + ${c}) % ${m}`);
    }
    for (let a = -16; a <= 32; a++) for (let c = -128; c <= 128; c++) {
      if (mod(v * a + c, m) === out) cands.push(`(v * ${a} + ${c}) % ${m}`);
    }
    for (let k = 0; k < 1024; k++) {
      if (mod((v ^ k), m) === out) cands.push(`(v ^ ${k}) % ${m}`);
      if (mod((v * 3 ^ k), m) === out) cands.push(`((v*3) ^ ${k}) % ${m}`);
      if (mod((v * 2 ^ k), m) === out) cands.push(`((v*2) ^ ${k}) % ${m}`);
      if (mod(((v + Math.floor(v/3)) ^ k), m) === out) cands.push(`((v + Math.floor(v/3)) ^ ${k}) % ${m}`);
    }
  }
  for (let k = 0; k < 4096; k++) if ((v ^ k) === out) cands.push(`v ^ ${k}`);
  // 唯一形状: %MOD 后 v ^ k
  for (const m of MODS) for (let k = 0; k < 1024; k++) {
    if ((mod(v,m) ^ k) === out) cands.push(`(v % ${m}) ^ ${k}`);
  }
  console.log(`--- s${String(n).padStart(2,"0")}: ${v} -> ${out}  (${cands.length})`);
  console.log("    " + [...new Set(cands)].slice(0, 25).join("\n    "));
}

import { readFileSync } from "node:fs";
const exp = JSON.parse(readFileSync(new URL("../tests/expected.json", import.meta.url), "utf8"));
const st = exp.stages;
const inputs = [exp.input, ...st.slice(0, -1)];
const mod = (a, m) => ((a % m) + m) % m;

function fit(shape, list) {
  const out = [];
  if (shape === "A") {
    // (v + floor(v/3) + c) % 997
    for (let c = -8; c <= 8; c++) {
      if (list.every(([n, v, o]) => mod(v + Math.floor(v / 3) + c, 997) === o)) out.push(`(v + Math.floor(v/3) + ${c}) % 997`);
    }
    for (let d = 2; d <= 6; d++) for (let c = -4; c <= 4; c++)
      if (list.every(([n, v, o]) => mod(v + Math.floor(v / d) + c, 997) === o)) out.push(`(v + Math.floor(v/${d}) + ${c}) % 997`);
  } else if (shape === "B") {
    // v ^ (((n+1)*k) % 64)  or  v ^ ((n*k) % 64) etc
    for (let mult = 0; mult <= 64; mult++) for (let add = -4; add <= 4; add++) for (let mm = 32; mm <= 128; mm *= 2) {
      if (list.every(([n, v, o]) => (v ^ (((n + add) * mult) % mm)) === o)) out.push(`v ^ (((n ${add >= 0 ? "+" : ""}${add}) * ${mult}) % ${mm})`);
    }
    for (let k = 0; k < 4096; k++) if (list.every(([n, v, o]) => (v ^ k) === o)) out.push(`v ^ ${k}`);
  } else if (shape === "C") {
    for (let a = 1; a <= 6; a++) for (let b = -64; b <= 64; b++) for (let m of [991, 997, 1000, 999, 1001, 1009])
      if (list.every(([n, v, o]) => mod(v * a - n + b, m) === o)) out.push(`(v * ${a} - n + ${b}) % ${m}`);
    for (let a = 1; a <= 6; a++) for (let b = -64; b <= 64; b++) for (let m of [991, 997, 1000, 999, 1001, 1009])
      if (list.every(([n, v, o]) => mod(v * a + b, m) === o)) out.push(`(v * ${a} + ${b}) % ${m}`);
  } else if (shape === "D") {
    for (let a = 1; a <= 6; a++) for (let b = -64; b <= 64; b++) for (let m of [1000, 991, 997, 999, 1001, 1009])
      if (list.every(([n, v, o]) => mod(v * a + b, m) === o)) out.push(`(v * ${a} + ${b}) % ${m}`);
    for (let a = 1; a <= 6; a++) for (let b = -64; b <= 64; b++) for (let m of [1000, 991, 997, 999, 1001, 1009])
      if (list.every(([n, v, o]) => mod(v * a - n + b, m) === o)) out.push(`(v * ${a} - n + ${b}) % ${m}`);
  }
  return out;
}

const groups = { A: [], B: [], C: [], D: [] };
for (let n = 1; n <= 32; n++) groups[["A", "B", "C", "D"][(n - 1) % 4]].push([n, inputs[n - 1], st[n - 1]]);

for (const k of ["A", "B", "C", "D"]) {
  console.log(`=== shape ${k}: stages ${groups[k].map(x => x[0]).join(",")}`);
  console.log(groups[k].map(([n, v, o]) => `  s${n}: ${v} -> ${o}`).join("\n"));
  const fits = fit(k, groups[k]);
  console.log("  FITS:", fits.length ? "\n    " + fits.join("\n    ") : "(none)");
}

